summary.candidateSort:
function mockCandidateSort(a,b){
  const sa=mockSeen(a),sb=mockSeen(b);
  if(sa!==sb)return sa-sb;
  const la=mockLastSeen(a),lb=mockLastSeen(b);
  if(la!==lb)return la.localeCompare(lb);
  return Math.random()-.5;
}

summary.finishMock:
function finishMock(timeup=false){
  recordMockQuestionTime();
  if(mockTimerHandle){clearInterval(mockTimerHandle);mockTimerHandle=null;}
  const used=Math.min(mockInitialSeconds,Math.max(0,mockInitialSeconds-mockSeconds));
  let correct=0,blank=0;
  const byCat={};
  const wrongs=[];

  mockItems.forEach((q,i)=>{
    const ans=mockAnswers[i];
    const ok=ans===q.a;
    const sourceId=q.sourceId||q.id;
    const ms=profile.mockQuestionStats[sourceId]||(profile.mockQuestionStats[sourceId]={seen:0,correct:0,lastSeen:null});
    ms.seen=(ms.seen||0)+1;
    if(ok)ms.correct=(ms.correct||0)+1;
    ms.lastSeen=localDateISO(0);
    if(ans===null) blank++;
    if(ok) correct++;
    if(!byCat[q.cat]) byCat[q.cat]={correct:0,total:0};
    byCat[q.cat].total++;
    if(ok) byCat[q.cat].correct++;
    ensureQuestionProfile();
    const st=profile.qStats[q.sourceId||q.id];
    const sec=mockQuestionSeconds[i]||0;
    if(!ok){
      wrongs.push({q,ans});
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.last=localDateISO(0);
        st.streak=0;
        if(ans===null && timeup) st.lastReason='時間不足';
        adaptiveMemoryUpdate(st,'wrong',sec,st.lastReason,false);
      }
      registerReviewJourney(q,'mock');
      applyQuestionSkillDelta(q,-1);
    }else{
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.correct=(st.correct||0)+1;
        st.last=localDateISO(0);
        st.streak=(st.streak||0)+1;
        adaptiveMemoryUpdate(st,'correct',sec,null,false);
      }
      applyQuestionSkillDelta(q,0.35);
    }
  });

  const total=mockItems.length;
  const rate=total?Math.round(correct/total*100):0;
  const wrong=total-correct-blank;

  const attemptDetails=mockItems.map((q,i)=>({
    id:q.sourceId||q.id,
    shownOptions:[...q.options],
    correctIndex:q.a,
    answerIndex:mockAnswers[i],
    flagged:!!mockFlags[i],
    seconds:mockQuestionSeconds[i]||0
  }));
  lastMockAttempt={
    date:localDateISO(0),mode:mockMode,total,correct,blank,rate,seconds:used,
    blueprint:mockCurrentBlueprint?structuredClone(mockCurrentBlueprint):null,
    byCat:structuredClone(byCat),details:attemptDetails
  };
  profile.mockHistory.unshift(lastMockAttempt);
  profile.mockHistory=profile.mockHistory.slice(0,10);
  profile.xp += Math.round(correct*2);
  saveProfile();

  document.getElementById('mockExam').classList.remove('show');
  document.getElementById('mockResult').classList.add('show');

  document.getElementById('mockResultScore').textContent=`${rate}%`;
  document.getElementById('mockStatCorrect').textContent=correct;
  document.getElementById('mockStatWrong').textContent=wrong;
  document.getElementById('mockStatBlank').textContent=blank;
  document.getElementById('mockStatTime').textContent=`${Math.floor(used/60)}m`;

  let message='弱点を見つけられたことが収穫です。';
  let icon='📚';
  if(rate>=85){message='かなり安定しています。見直し問題を中心に仕上げましょう。';icon='🏆';}
  else if(rate>=70){message='良い位置です。誤答分野を復習するとさらに安定します。';icon='🎯';}
  else if(rate>=55){message='基礎はつながっています。弱点の再学習を優先しましょう。';icon='📈';}
  if(timeup) message='時間終了です。未回答を含めて、時間配分も復習材料にしましょう。';
  document.getElementById('mockResultIcon').textContent=icon;
  document.getElementById('mockResultMessage').textContent=message;
  renderMockDiagnosis(lastMockAttempt,byCat);

  const breakdown=document.getElementById('mockBreakdown');
  breakdown.innerHTML='';
  Object.entries(byCat).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total)).forEach(([cat,v])=>{
    const pct=Math.round(v.correct/v.total*100);
    const d=document.createElement('div');
    d.className='mock-break-row';
    d.innerHTML=`<div class="mock-break-name">${cat}</div><div class="progress"><div style="width:${pct}%"></div></div><div class="mock-break-pct">${pct}%</div>`;
    breakdown.appendChild(d);
  });

  const review=document.getElementById('mockReviewList');
  review.innerHTML='';
  wrongs.slice(0,8).forEach(x=>{
    const d=document.createElement('div');
    d.className='mock-review-item';
    const selected=x.ans===null?'未回答':x.q.options[x.ans];
    const stat=profile.mockMistakeStats?.[x.q.sourceId||x.q.id];
    const j=journeyFor(x.q.sourceId||x.q.id);
    const reason=stat?.lastReason||'原因未記録';
    d.innerHTML=`<b>${x.q.cat}・${x.q.concept}</b><div class="sub">${escapeHtml(x.q.q)}<br>あなた：${escapeHtml(selected)} ／ 正解：${escapeHtml(x.q.options[x.q.a])}</div><div class="sub">原因：${escapeHtml(reason)}${j?` ／ 復習：${journeyStageLabel(j.stage)}`:''}</div>`;
    review.appendChild(d);
  });
  if(!wrongs.length) review.innerHTML='<div class="sub">全問正解です 🎉</div>';

  const reviewBtn=document.getElementById('mockStartReview');
  if(reviewBtn){
    const hasReview=reviewCandidates(lastMockAttempt).length>0;
    reviewBtn.style.display=hasReview?'':'none';
    reviewBtn.classList.toggle('primary-action',hasReview);
    document.getElementById('mockBackMenu')?.classList.toggle('primary-action',!hasReview);
  }
  renderMockHistory();
  renderDailyPlan();
  renderReadiness();
}

summary.buildMockQuestions:
function(modeOrCount){
  const mode=typeof modeOrCount==='string'?modeOrCount:(modeOrCount===60?'full':'half');
  const bp=MOCK_BLUEPRINTS[mode]||MOCK_BLUEPRINTS.full;
  const quotas=mockCategoryQuotas(bp.count);
  const difficultyByCat=allocateMockDifficultyByCategory(quotas,bp);
  const conceptCounts={};
  const cognitiveCounts={'想起':0,'適用':0,'判断':0};
  const cognitiveTarget=bp.cognitive||{'想起':0,'適用':bp.count,'判断':0};
  const out=[];
  const categoryOrder=shuffled([...MOCK_CATEGORIES]);

  categoryOrder.forEach(cat=>{
    const cap=mode==='half'?1:2;
    MOCK_DIFFICULTY_LEVELS.forEach(level=>{
      const n=difficultyByCat[cat][level]||0;
      const pool=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty===level);
      out.push(...pickMockPool(pool,n,conceptCounts,cap,cognitiveCounts,cognitiveTarget,level));
    });
  });

  const unique=[];
  const seenIds=new Set();
  for(const q of out){
    if(!seenIds.has(q.id)){unique.push(q);seenIds.add(q.id);}
  }
  if(unique.length<bp.count){
    unique.push(...QUESTION_BANK.filter(q=>!seenIds.has(q.id)).sort(mockCandidateSort).slice(0,bp.count-unique.length));
  }

  const picked=shuffled(unique.slice(0,bp.count));
  const counts={
    categories:Object.fromEntries(MOCK_CATEGORIES.map(c=>[c,picked.filter(q=>q.cat===c).length])),
    difficulty:Object.fromEntries(MOCK_DIFFICULTY_LEVELS.map(level=>[level,picked.filter(q=>q.difficulty===level).length])),
    cognitive:Object.fromEntries(MOCK_COGNITIVE_LEVELS.map(level=>[level,picked.filter(q=>q.cognitiveLevel===level).length])),
    unseen:picked.filter(q=>mockSeen(q)===0).length
  };
  mockCurrentBlueprint={mode,count:bp.count,quotas,difficultyByCat,counts};
  return picked.map(randomizeMockQuestion);
}
